CREATE TYPE "UserStatus" AS ENUM ('ACTIVE','SUSPENDED','DELETED');
CREATE TYPE "CustomerSegment" AS ENUM ('RETAIL','WHOLESALE','BUSINESS');
CREATE TYPE "VerificationStatus" AS ENUM ('NOT_REQUIRED','PENDING','VERIFIED','REJECTED');
CREATE TYPE "CustomerTier" AS ENUM ('STANDARD','TIER_A','TIER_B','ENTERPRISE');
CREATE TYPE "OrderStatus" AS ENUM ('PLACED','CONFIRMED','PROCESSING','READY_FOR_DISPATCH','OUT_FOR_DELIVERY','DELIVERED','CANCELLED');
CREATE TYPE "PaymentMethod" AS ENUM ('COD','CARD','MOBILE_WALLET','CREDIT_INVOICE','MANUAL_TRANSFER');
CREATE TYPE "PaymentStatus" AS ENUM ('PENDING','PENDING_VERIFICATION','PAID','FAILED','PARTIALLY_REFUNDED','REFUNDED');
CREATE TYPE "InventoryMovementType" AS ENUM ('RECEIPT','RESERVATION','RESERVATION_RELEASE','SALE','ADJUSTMENT','RETURN');

CREATE TABLE "users" ("id" UUID NOT NULL,"firebase_uid" TEXT NOT NULL,"email" TEXT,"phone" TEXT,"display_name" TEXT,"status" "UserStatus" NOT NULL DEFAULT 'ACTIVE',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "users_pkey" PRIMARY KEY ("id"));
CREATE TABLE "roles" ("id" UUID NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "roles_pkey" PRIMARY KEY ("id"));
CREATE TABLE "permissions" ("id" UUID NOT NULL,"code" TEXT NOT NULL,"description" TEXT,CONSTRAINT "permissions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "user_roles" ("user_id" UUID NOT NULL,"role_id" UUID NOT NULL,"assigned_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "user_roles_pkey" PRIMARY KEY ("user_id","role_id"));
CREATE TABLE "role_permissions" ("role_id" UUID NOT NULL,"permission_id" UUID NOT NULL,CONSTRAINT "role_permissions_pkey" PRIMARY KEY ("role_id","permission_id"));
CREATE TABLE "customer_profiles" ("id" UUID NOT NULL,"user_id" UUID NOT NULL,"segment" "CustomerSegment" NOT NULL DEFAULT 'RETAIL',"verification_status" "VerificationStatus" NOT NULL DEFAULT 'NOT_REQUIRED',"approved_tier" "CustomerTier" NOT NULL DEFAULT 'STANDARD',"credit_limit" DECIMAL(14,2) NOT NULL DEFAULT 0,"credit_used" DECIMAL(14,2) NOT NULL DEFAULT 0,"loyalty_points" INTEGER NOT NULL DEFAULT 0,"tax_registration_no" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "customer_profiles_pkey" PRIMARY KEY ("id"));
CREATE TABLE "addresses" ("id" UUID NOT NULL,"user_id" UUID NOT NULL,"label" TEXT,"recipient_name" TEXT NOT NULL,"phone" TEXT NOT NULL,"country_code" TEXT NOT NULL DEFAULT 'EG',"city" TEXT NOT NULL,"area" TEXT,"street" TEXT NOT NULL,"building" TEXT,"floor" TEXT,"latitude" DECIMAL(10,7),"longitude" DECIMAL(10,7),"is_default" BOOLEAN NOT NULL DEFAULT false,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "addresses_pkey" PRIMARY KEY ("id"));
CREATE TABLE "warehouses" ("id" UUID NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"is_active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "warehouses_pkey" PRIMARY KEY ("id"));
CREATE TABLE "categories" ("id" UUID NOT NULL,"parent_id" UUID,"slug" TEXT NOT NULL,"name_ar" TEXT NOT NULL,"name_en" TEXT NOT NULL,"sort_order" INTEGER NOT NULL DEFAULT 0,"is_active" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "categories_pkey" PRIMARY KEY ("id"));
CREATE TABLE "products" ("id" UUID NOT NULL,"category_id" UUID,"sku" TEXT NOT NULL,"slug" TEXT NOT NULL,"name_ar" TEXT NOT NULL,"name_en" TEXT NOT NULL,"description_ar" TEXT,"description_en" TEXT,"base_unit" TEXT NOT NULL,"units_per_carton" INTEGER,"min_order_qty" INTEGER NOT NULL DEFAULT 1,"is_active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "products_pkey" PRIMARY KEY ("id"));
CREATE TABLE "product_prices" ("id" UUID NOT NULL,"product_id" UUID NOT NULL,"segment" "CustomerSegment" NOT NULL,"tier" "CustomerTier" NOT NULL DEFAULT 'STANDARD',"unit_price" DECIMAL(14,2) NOT NULL,"currency" TEXT NOT NULL DEFAULT 'EGP',"valid_from" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"valid_until" TIMESTAMP(3),CONSTRAINT "product_prices_pkey" PRIMARY KEY ("id"));
CREATE TABLE "inventory_balances" ("id" UUID NOT NULL,"warehouse_id" UUID NOT NULL,"product_id" UUID NOT NULL,"quantity" INTEGER NOT NULL DEFAULT 0,"reserved_quantity" INTEGER NOT NULL DEFAULT 0,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "inventory_balances_pkey" PRIMARY KEY ("id"));
CREATE TABLE "inventory_ledger" ("id" UUID NOT NULL,"warehouse_id" UUID NOT NULL,"product_id" UUID NOT NULL,"actor_user_id" UUID,"movement" "InventoryMovementType" NOT NULL,"quantity" INTEGER NOT NULL,"reference" TEXT,"note" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "inventory_ledger_pkey" PRIMARY KEY ("id"));
CREATE TABLE "orders" ("id" UUID NOT NULL,"order_number" TEXT NOT NULL,"user_id" UUID NOT NULL,"address_id" UUID,"status" "OrderStatus" NOT NULL DEFAULT 'PLACED',"currency" TEXT NOT NULL DEFAULT 'EGP',"subtotal" DECIMAL(14,2) NOT NULL,"discount_total" DECIMAL(14,2) NOT NULL DEFAULT 0,"tax_total" DECIMAL(14,2) NOT NULL DEFAULT 0,"shipping_fee" DECIMAL(14,2) NOT NULL DEFAULT 0,"grand_total" DECIMAL(14,2) NOT NULL,"notes" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "orders_pkey" PRIMARY KEY ("id"));
CREATE TABLE "order_items" ("id" UUID NOT NULL,"order_id" UUID NOT NULL,"product_id" UUID NOT NULL,"product_sku" TEXT NOT NULL,"product_name" TEXT NOT NULL,"quantity" INTEGER NOT NULL,"unit_price" DECIMAL(14,2) NOT NULL,"line_total" DECIMAL(14,2) NOT NULL,CONSTRAINT "order_items_pkey" PRIMARY KEY ("id"));
CREATE TABLE "payments" ("id" UUID NOT NULL,"order_id" UUID NOT NULL,"method" "PaymentMethod" NOT NULL,"status" "PaymentStatus" NOT NULL DEFAULT 'PENDING',"amount" DECIMAL(14,2) NOT NULL,"currency" TEXT NOT NULL DEFAULT 'EGP',"provider" TEXT,"provider_reference" TEXT,"idempotency_key" TEXT,"verified_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "payments_pkey" PRIMARY KEY ("id"));
CREATE TABLE "audit_logs" ("id" UUID NOT NULL,"actor_user_id" UUID,"action" TEXT NOT NULL,"entity_type" TEXT NOT NULL,"entity_id" TEXT,"request_id" TEXT,"metadata" JSONB,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "audit_logs_pkey" PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "users_firebase_uid_key" ON "users"("firebase_uid");
CREATE UNIQUE INDEX "users_email_key" ON "users"("email");
CREATE UNIQUE INDEX "users_phone_key" ON "users"("phone");
CREATE UNIQUE INDEX "roles_code_key" ON "roles"("code");
CREATE UNIQUE INDEX "permissions_code_key" ON "permissions"("code");
CREATE UNIQUE INDEX "customer_profiles_user_id_key" ON "customer_profiles"("user_id");
CREATE INDEX "addresses_user_id_is_default_idx" ON "addresses"("user_id","is_default");
CREATE UNIQUE INDEX "warehouses_code_key" ON "warehouses"("code");
CREATE UNIQUE INDEX "categories_slug_key" ON "categories"("slug");
CREATE INDEX "categories_parent_id_sort_order_idx" ON "categories"("parent_id","sort_order");
CREATE UNIQUE INDEX "products_sku_key" ON "products"("sku");
CREATE UNIQUE INDEX "products_slug_key" ON "products"("slug");
CREATE INDEX "products_category_id_is_active_idx" ON "products"("category_id","is_active");
CREATE INDEX "product_prices_product_id_segment_tier_valid_from_idx" ON "product_prices"("product_id","segment","tier","valid_from");
CREATE UNIQUE INDEX "inventory_balances_warehouse_id_product_id_key" ON "inventory_balances"("warehouse_id","product_id");
CREATE INDEX "inventory_ledger_warehouse_id_product_id_created_at_idx" ON "inventory_ledger"("warehouse_id","product_id","created_at");
CREATE UNIQUE INDEX "orders_order_number_key" ON "orders"("order_number");
CREATE INDEX "orders_user_id_created_at_idx" ON "orders"("user_id","created_at");
CREATE INDEX "orders_status_created_at_idx" ON "orders"("status","created_at");
CREATE INDEX "order_items_order_id_idx" ON "order_items"("order_id");
CREATE UNIQUE INDEX "payments_idempotency_key_key" ON "payments"("idempotency_key");
CREATE INDEX "payments_order_id_status_idx" ON "payments"("order_id","status");
CREATE INDEX "payments_provider_provider_reference_idx" ON "payments"("provider","provider_reference");
CREATE INDEX "audit_logs_entity_type_entity_id_created_at_idx" ON "audit_logs"("entity_type","entity_id","created_at");
CREATE INDEX "audit_logs_actor_user_id_created_at_idx" ON "audit_logs"("actor_user_id","created_at");

ALTER TABLE "user_roles" ADD CONSTRAINT "user_roles_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "user_roles" ADD CONSTRAINT "user_roles_role_id_fkey" FOREIGN KEY ("role_id") REFERENCES "roles"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "role_permissions" ADD CONSTRAINT "role_permissions_role_id_fkey" FOREIGN KEY ("role_id") REFERENCES "roles"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "role_permissions" ADD CONSTRAINT "role_permissions_permission_id_fkey" FOREIGN KEY ("permission_id") REFERENCES "permissions"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "customer_profiles" ADD CONSTRAINT "customer_profiles_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
